attribute vec4 iSeed;
uniform float uTime;
uniform vec4 uArea;      // minX, minZ, sizeX, sizeZ
uniform float uTop;
uniform float uBottom;
uniform float uSpeed;
uniform vec2 uWind;      // trôi ngang / đơn vị rơi
uniform vec2 uSize;      // rộng, dài
uniform float uSnow;
uniform float uAmount;
uniform sampler2D uMask; // R = cường độ 0…1, G = độ cao chân mây (0…1 của uTop)
varying vec2 vUv;
varying float vFade;
void main() {
  vUv = uv;
  vec2 cell = uArea.xy + iSeed.xy * uArea.zw;
  vec4 m = texture2D(uMask, iSeed.xy);
  float top = m.g > 0.0 ? mix(uBottom, uTop, m.g) : uTop;
  float H = uTop - uBottom;
  float t = fract(uTime * uSpeed / H + iSeed.z);
  float y = top - t * H;
  float fall = top - y;
  vec3 c = vec3(cell.x + uWind.x * fall, y, cell.y + uWind.y * fall);
  c.x += uSnow * sin(uTime * 1.3 + iSeed.w * 40.0) * 0.25;
  c.z += uSnow * cos(uTime * 1.1 + iSeed.w * 30.0) * 0.25;
  float g = groundAt(c.xz);
  float on = step(iSeed.w, m.r * uAmount) * step(g, c.y) * step(c.y, top);
  vFade = smoothstep(g, g + 0.6, c.y) * smoothstep(top, top - 0.8, c.y);
  vec3 vel = normalize(vec3(uWind.x, -1.0, uWind.y));
#ifdef PRECIP_LOCAL
  // Toạ độ cục bộ của mesh (vùng rơi, mặt đất) → thế giới theo ma trận cha (nhóm đã dời/xoay/thu phóng).
  c = (modelMatrix * vec4(c, 1.0)).xyz;
  vel = normalize(mat3(modelMatrix) * vel);
  float ws = length(modelMatrix[0].xyz);
#else
  float ws = 1.0;
#endif
  vec3 toCam = normalize(cameraPosition - c);
  vec3 right = normalize(cross(vel, toCam));
  vec3 upv = mix(vel, normalize(cross(toCam, right)), uSnow);
  vec3 p = c + (right * position.x * uSize.x + upv * position.y * uSize.y) * ws;
  vec4 mvPosition = viewMatrix * vec4(p, 1.0);
  gl_Position = on > 0.5 ? projectionMatrix * mvPosition : vec4(2.0, 2.0, 2.0, 1.0);
  #include <fog_vertex>
}

