#ifndef PRIMARY_STEPS
#define PRIMARY_STEPS 12
#endif
#ifndef LIGHT_STEPS
#define LIGHT_STEPS 4
#endif
uniform vec3 sunDir;
uniform vec3 center;
uniform float planetRadius;
uniform float atmosRadius;
uniform float scaleHeightR;
uniform float scaleHeightM;
uniform vec3 betaR;
uniform float betaM;
uniform float mieG;
uniform float sunIntensity;
uniform float intensity;
uniform float limbBoost;   // tăng sáng phần khí quyển ngoài mép (không đè lên mặt đất)
varying vec3 vPosW;

vec2 raySphere(vec3 ro, vec3 rd, float r) {
  float b = dot(ro, rd);
  float c = dot(ro, ro) - r * r;
  float d = b * b - c;
  if (d < 0.0) return vec2(1e9, -1e9);
  d = sqrt(d);
  return vec2(-b - d, -b + d);
}

void main() {
  vec3 ro = cameraPosition - center;
  vec3 rd = normalize(vPosW - cameraPosition);
  vec3 L = normalize(sunDir);
  vec2 ta = raySphere(ro, rd, atmosRadius);
  if (ta.x > ta.y) discard;
  vec2 tp = raySphere(ro, rd, planetRadius);
  float t0 = max(ta.x, 0.0);
  float t1 = tp.x > 0.0 && tp.x < ta.y ? tp.x : ta.y;
  float ds = (t1 - t0) / float(PRIMARY_STEPS);
  vec3 sumR = vec3(0.0);
  vec3 sumM = vec3(0.0);
  float odR = 0.0;
  float odM = 0.0;
  for (int i = 0; i < PRIMARY_STEPS; i++) {
    vec3 p = ro + rd * (t0 + ds * (float(i) + 0.5));
    float h = length(p) - planetRadius;
    float dR = exp(-h / scaleHeightR) * ds;
    float dM = exp(-h / scaleHeightM) * ds;
    odR += dR;
    odM += dM;
    vec2 tl = raySphere(p, L, atmosRadius);
    float dl = tl.y / float(LIGHT_STEPS);
    float lR = 0.0;
    float lM = 0.0;
    bool shadow = false;
    for (int j = 0; j < LIGHT_STEPS; j++) {
      vec3 q = p + L * (dl * (float(j) + 0.5));
      float hq = length(q) - planetRadius;
      if (hq < 0.0) { shadow = true; break; }
      lR += exp(-hq / scaleHeightR) * dl;
      lM += exp(-hq / scaleHeightM) * dl;
    }
    if (shadow) continue;
    vec3 tau = betaR * (odR + lR) + betaM * 1.1 * (odM + lM);
    vec3 att = exp(-tau);
    sumR += dR * att;
    sumM += dM * att;
  }
  float mu = dot(rd, L);
  float pR = 3.0 / (16.0 * 3.14159265) * (1.0 + mu * mu);
  float g2 = mieG * mieG;
  float pM = 3.0 / (8.0 * 3.14159265) * ((1.0 - g2) * (1.0 + mu * mu)) / ((2.0 + g2) * pow(1.0 + g2 - 2.0 * mieG * mu, 1.5));
  float bb = dot(ro, rd);
  float hc = (sqrt(max(dot(ro, ro) - bb * bb, 0.0)) - planetRadius) / (atmosRadius - planetRadius);
  float limb = mix(1.0, limbBoost, smoothstep(-0.6, 0.15, hc));
  vec3 col = sunIntensity * intensity * limb * (sumR * betaR * pR + sumM * betaM * pM);
  gl_FragColor = vec4(col, 1.0);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}

