varying vec3 vSLocal;
varying float vSTop;
uniform float uStrataTop;
uniform vec4 uSoil;    // bề dày lớp phủ bám mặt đất, màu
uniform float uLayerBottom[MAX_LAYERS];
uniform vec3 uLayerColor[MAX_LAYERS];
uniform float uLayerPattern[MAX_LAYERS];
uniform float uLayerPorous[MAX_LAYERS];
uniform int uLayerCount;
uniform vec3 uFold;    // biên độ, bước sóng, pha
uniform vec4 uFault;   // x, góc dốc (độ), throw, dấu (−1 thuận, +1 nghịch)
uniform vec3 uUplift;  // lượng, tâm, nửa bề rộng
uniform vec2 uRift;    // nửa bề rộng, độ sụt
uniform vec3 uWater;   // bật, mực (y), có lớp thấm được đánh dấu
uniform vec3 uWaterColor;
uniform sampler2D uWaterTex; // mực nước theo x (R, half float) khi uWaterVar.x = 1
uniform vec3 uWaterVar;      // bật đường cong, minX, sizeX
float sHash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float sNoise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(sHash(i), sHash(i + vec2(1, 0)), u.x), mix(sHash(i + vec2(0, 1)), sHash(i + vec2(1, 1)), u.x), u.y);
}
float sCot() { return 1.0 / tan(radians(clamp(uFault.y, 5.0, 90.0))); }
float sFaultSide(float x, float y) { return x > uFault.x - y * sCot() ? 1.0 : 0.0; }
float sRiftSide(float x, float y) {
  if (uRift.y == 0.0) return 0.0;
  float l = uFault.x - uRift.x - y * sCot();
  float r = uFault.x + uRift.x + y * sCot();
  return (x > l && x < r) ? 1.0 : 0.0;
}
float sDisp(float x, float y) {
  float fold = uFold.x * sin(6.2831853 * x / max(0.1, uFold.y) + uFold.z);
  float u = (x - uUplift.y) / max(0.1, uUplift.z);
  return fold + uUplift.x * exp(-u * u) + sFaultSide(x, y) * uFault.w * uFault.z - sRiftSide(x, y) * uRift.y;
}
// Mẫu kí hiệu đá theo toạ độ (u dọc mặt, y0 độ sâu gốc). Trả hệ số tối (0 = không đổi).
float sPattern(float pat, vec2 p) {
  if (pat < 0.5) return 0.0;
  if (pat < 1.5) { // chấm (cát, cuội)
    vec2 c = p * vec2(4.0, 5.0);
    vec2 g = fract(c + vec2(floor(c.y) * 0.5, 0.0)) - 0.5;
    float r = 0.12 + 0.1 * sHash(floor(c + vec2(floor(c.y) * 0.5, 0.0)));
    return 1.0 - smoothstep(r - 0.05, r, length(g));
  }
  if (pat < 2.5) { // gạch ngang ngắn (sét, phiến)
    vec2 c = p * vec2(2.2, 7.0);
    float row = floor(c.y);
    float x = fract(c.x + sHash(vec2(row, 3.0)));
    float line = 1.0 - smoothstep(0.05, 0.12, abs(fract(c.y) - 0.5));
    return line * step(0.25, x) * step(x, 0.85);
  }
  vec2 c = p * vec2(2.0, 3.6); // gạch xây (đá vôi)
  float row = floor(c.y);
  float bx = fract(c.x + mod(row, 2.0) * 0.5);
  float by = fract(c.y);
  float joint = max(1.0 - smoothstep(0.0, 0.06, by), 1.0 - smoothstep(0.0, 0.035, min(bx, 1.0 - bx)));
  return joint;
}

