  float c = texture2D(cloudMap, vUv).r;
  float a = smoothstep(0.12, 0.85, c);
  a = pow(a, 0.9) * opacity;
  if (a < 0.003) discard;
  vec3 N = normalize(vNormalW);
  float mu = dot(N, normalize(sunDir));
  float lit = smoothstep(-twilight * 0.6, twilight * 1.2, mu) * (0.35 + 0.65 * max(mu, 0.0));
  float lowSun = 1.0 - smoothstep(0.0, 0.4, mu);
  vec3 tint = mix(vec3(1.0), vec3(1.0, 0.55, 0.32), lowSun * 0.9);
  // Mây dày sáng hơn mép mỏng một chút.
  vec3 col = sunColor * tint * sunIntensity * lit * (0.82 + 0.18 * c) + vec3(0.004, 0.005, 0.008);
  gl_FragColor = vec4(col, a);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}

