#ifdef USE_SPLAT
uniform highp sampler2DArray uSplat;
uniform highp sampler2DArray uSplatN;
#endif
float tHash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float tNoise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(tHash(i), tHash(i + vec2(1, 0)), u.x), mix(tHash(i + vec2(0, 1)), tHash(i + vec2(1, 1)), u.x), u.y);
}
float tFbm(vec2 p) { return 0.5 * tNoise(p) + 0.3 * tNoise(p * 2.13 + 7.1) + 0.2 * tNoise(p * 4.37 - 3.3); }
vec3 tLayer(int k, vec2 uv, float vary) {
#ifdef USE_SPLAT
  vec3 a = texture(uSplat, vec3(uv, float(k))).rgb;
  vec3 b = texture(uSplat, vec3(uv * 0.23 + 0.37, float(k))).rgb;
  return mix(a, b, vary) * uTint[k];
#else
  return uTint[k] * (0.82 + 0.36 * tFbm(uv * 3.0 + float(k) * 11.0));
#endif
}
vec3 tLayerN(int k, vec2 uv) {
#ifdef USE_SPLAT
  return texture(uSplatN, vec3(uv, float(k))).xyz * 2.0 - 1.0;
#else
  return vec3(0.0, 0.0, 1.0);
#endif
}
// Trọng số 6 lớp tại điểm hiện tại.
void terrainWeights(out float w[6], out float wet) {
  float elev = (vTWorld.y - uSeaLevel) * uMpu;
  float slope = 1.0 - clamp(vTNormal.y, 0.0, 1.0);
  float n = tFbm(vTWorld.xz * 0.35);
  float n2 = tFbm(vTWorld.xz * 1.7 + 4.0);
  float dry = dryAt(vTWorld.xz);
  float sand = 1.0 - smoothstep(2.0 + n * 5.0, 9.0 + n * 10.0, elev);
  float alpine = smoothstep(uTreeLine - 250.0 + n * 300.0, uTreeLine + 200.0, elev);
  float rock = smoothstep(uRockSlope + n * 0.1, uRockSlope + 0.16 + n * 0.08, slope);
  rock = max(rock, alpine * smoothstep(0.12, 0.3, slope + n2 * 0.15));
  rock = max(rock, smoothstep(uTreeLine + 300.0, uTreeLine + 1100.0, elev + n * 300.0) * 0.85);
  float snow = smoothstep(uSnowLine - 200.0 + n * 260.0, uSnowLine + 80.0, elev) * (1.0 - smoothstep(0.55, 0.8, slope)) * uSnowAmount;
  w[0] = sand * (1.0 - rock * 0.5);
  float veg = (1.0 - w[0]) * (1.0 - rock) * (1.0 - snow);
  w[1] = veg * (1.0 - alpine) * (1.0 - dry);
  w[2] = veg * alpine * (1.0 - dry * 0.7);
  w[3] = veg * (dry * (1.0 - alpine) + dry * 0.7 * alpine);
  w[4] = (1.0 - w[0]) * rock * (1.0 - snow);
  w[5] = snow;
  wet = 1.0 - smoothstep(-2.0, 3.0, elev);
}

