float sx = vSLocal.x;
float sy = vSLocal.y;
float y0 = sy - sDisp(sx, sy) - uStrataTop;
int sk = uLayerCount - 1;
float sTopB = 0.0;
float sBotB = uLayerBottom[uLayerCount - 1];
for (int k = 0; k < MAX_LAYERS; k++) {
  if (k >= uLayerCount) break;
  if (-y0 < uLayerBottom[k]) { sk = k; sBotB = uLayerBottom[k]; sTopB = k == 0 ? -1e4 : uLayerBottom[k - 1]; break; }
}
vec3 sCol = uLayerColor[sk];
vec2 sp = vec2(vSLocal.x + vSLocal.z, y0);
float grain = sNoise(sp * 9.0) * 0.6 + sNoise(sp * 31.0) * 0.4;
sCol *= 0.86 + 0.24 * grain;
sCol *= 0.92 + 0.08 * sin(y0 * 40.0 + sNoise(sp * 2.0) * 6.0); // phân lớp mỏng
sCol = mix(sCol, sCol * 0.55, sPattern(uLayerPattern[sk], sp) * 0.75);
// Ranh giới lớp: nét tối mảnh, khử răng cưa theo fwidth.
float sDepth = -y0;
float sDist = min(abs(sDepth - sTopB), abs(sBotB - sDepth));
float sw = fwidth(y0) * 1.2 + 0.004;
sCol = mix(sCol * 0.45, sCol, smoothstep(sw, sw * 2.2, sDist));
// Mặt đứt gãy (và hai đứt gãy địa hào): vạch đậm.
float sCt = sCot();
float sDip = radians(clamp(uFault.y, 5.0, 90.0));
float sF = 1e4;
if (uFault.z != 0.0) sF = abs(sx - (uFault.x - sy * sCt)) * sin(sDip);
if (uRift.y != 0.0) {
  sF = min(sF, abs(sx - (uFault.x - uRift.x - sy * sCt)) * sin(sDip));
  sF = min(sF, abs(sx - (uFault.x + uRift.x + sy * sCt)) * sin(sDip));
}
float fw = fwidth(sx) * 1.5 + 0.02;
sCol = mix(vec3(0.12, 0.08, 0.07), sCol, smoothstep(fw, fw * 2.0, sF));
// Nước ngầm: đới bão hoà dưới mực nước ở lớp thấm (mực phẳng uWater.y hoặc theo x từ uWaterTex).
float sWL = uWaterVar.x > 0.5 ? texture2D(uWaterTex, vec2(clamp((sx - uWaterVar.y) / uWaterVar.z, 0.0, 1.0), 0.5)).r : uWater.y;
if (uWater.x > 0.5 && sy < sWL && (uWater.z < 0.5 || uLayerPorous[sk] > 0.5)) {
  float ripple = 0.5 + 0.5 * sNoise(sp * 6.0);
  sCol = mix(sCol, uWaterColor * (0.8 + 0.3 * ripple), 0.45);
}
if (uWater.x > 0.5) sCol = mix(vec3(0.35, 0.75, 1.0), sCol, smoothstep(0.015, 0.04, abs(sy - sWL)));
// Lớp phủ thổ nhưỡng bám theo mặt đất (aTop = độ cao mặt đất của cột).
float sSoil = vSTop - sy;
if (uSoil.x > 0.0 && sSoil < uSoil.x * (0.8 + 0.4 * sNoise(sp * 1.5))) {
  vec3 soil = uSoil.yzw * (0.8 + 0.35 * grain);
  soil = mix(soil * 0.75, soil, smoothstep(0.0, uSoil.x, sSoil)); // mùn sẫm trên cùng
  sCol = soil;
}
diffuseColor.rgb *= sCol;

