uniform vec3 ngp;      // cực Bắc thiên hà (ECI)
uniform vec3 gc;       // tâm thiên hà (ECI)
uniform float intensity;
varying vec3 vDir;
float hash(vec3 p) { p = fract(p * 0.3183099 + 0.1); p *= 17.0; return fract(p.x * p.y * p.z * (p.x + p.y + p.z)); }
float noise(vec3 x) {
  vec3 i = floor(x); vec3 f = fract(x); f = f * f * (3.0 - 2.0 * f);
  return mix(mix(mix(hash(i), hash(i + vec3(1,0,0)), f.x), mix(hash(i + vec3(0,1,0)), hash(i + vec3(1,1,0)), f.x), f.y),
             mix(mix(hash(i + vec3(0,0,1)), hash(i + vec3(1,0,1)), f.x), mix(hash(i + vec3(0,1,1)), hash(i + vec3(1,1,1)), f.x), f.y), f.z);
}
float fbm(vec3 p) { float s = 0.0; float a = 0.5; for (int i = 0; i < 5; i++) { s += a * noise(p); p *= 2.03; a *= 0.5; } return s; }
void main() {
  vec3 d = normalize(vDir);
  float b = asin(clamp(dot(d, ngp), -1.0, 1.0));
  float cl = dot(normalize(d - ngp * dot(d, ngp)), gc);       // cos kinh độ thiên hà
  float bulge = 0.35 + 0.65 * pow(max(cl, 0.0), 3.0);
  float band = exp(-pow(b / (0.11 + 0.08 * bulge), 2.0));
  float n = fbm(d * 5.0);
  float dust = smoothstep(0.42, 0.7, fbm(d * 9.0 + 3.1)) * exp(-pow(b / 0.05, 2.0));
  float v = band * (0.25 + 0.95 * n) * bulge * (1.0 - 0.75 * dust);
  vec3 col = mix(vec3(0.55, 0.62, 0.85), vec3(1.0, 0.86, 0.68), bulge * 0.8) * v * intensity;
  gl_FragColor = vec4(col, 1.0);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}

