uniform highp sampler3D uDyeTex;
uniform mat4 uDyeInv;
uniform vec3 uDyeMin;
uniform vec3 uDyeSize;
uniform vec3 uDyeAbs;
uniform float uDyeK;
vec3 dyeTransmittance(vec3 wp, vec3 view) {
  vec3 p = (uDyeInv * vec4(wp, 1.0)).xyz;
  vec3 d = normalize((uDyeInv * vec4(-view, 0.0)).xyz);
  vec3 dd = vec3(abs(d.x) < 1e-4 ? 1e-4 : d.x, abs(d.y) < 1e-4 ? 1e-4 : d.y, abs(d.z) < 1e-4 ? 1e-4 : d.z);
  vec3 t1 = (uDyeMin - p) / dd;
  vec3 t2 = (uDyeMin + uDyeSize - p) / dd;
  // Cả đoạn thẳng qua điểm mặt (hai phía): mặt trước nhìn vào khối, mặt sau (pass transmission vẽ mặt sau) nhìn ngược lại.
  vec3 tmx = max(t1, t2);
  vec3 tmn = min(t1, t2);
  float tf = min(min(tmx.x, tmx.y), tmx.z);
  float tb = max(max(tmn.x, tmn.y), tmn.z);
  float h = max(tf - tb, 0.0) / float(DYE_STEPS);
  float acc = 0.0;
  for (int i = 0; i < DYE_STEPS; i++) {
    vec3 uvw = (p + d * (tb + (float(i) + 0.5) * h) - uDyeMin) / uDyeSize;
    acc += texture(uDyeTex, clamp(uvw, 0.0, 1.0)).r;
  }
  return exp(-uDyeK * uDyeAbs * acc * h);
}

