#define PI 3.141592653589793
uniform sampler2D dayMap;
uniform sampler2D nightMap;
uniform sampler2D waterMap;
#ifdef USE_NORMALMAP
uniform sampler2D normalMap;
uniform float normalStrength;
#endif
#ifdef USE_CLOUDS
uniform sampler2D cloudMap;
uniform float cloudOffset;   // lệch u của lớp mây so với mặt đất (vòng)
uniform float cloudHeight;   // độ cao lớp mây (đơn vị bán kính) cho bóng
uniform float cloudShadow;   // độ đậm bóng mây 0…1
uniform float cloudAmount;   // 0 = tắt mây (ẩn lớp mây)
#endif
uniform vec3 sunDir;
uniform vec3 sunColor;
uniform float sunIntensity;
uniform vec3 axisW;
uniform float nightGain;
uniform float specStrength;
uniform float twilight;      // độ rộng vùng chạng vạng (theo cos góc)
uniform float ambient;
varying vec2 vUv;
varying vec3 vNormalW;
varying vec3 vPosW;

float cloudCover(vec2 uv) {
#ifdef USE_CLOUDS
  float c = texture2D(cloudMap, uv).r;
  return smoothstep(0.12, 0.85, c);
#else
  return 0.0;
#endif
}

void main() {
  vec3 Ng = normalize(vNormalW);
  vec3 L = normalize(sunDir);
  vec3 V = normalize(cameraPosition - vPosW);
  vec3 E = cross(axisW, Ng);
  E = length(E) < 1e-4 ? vec3(1.0, 0.0, 0.0) : normalize(E);
  vec3 Nn = cross(Ng, E);
  vec3 N = Ng;
#ifdef USE_NORMALMAP
  vec3 t = texture2D(normalMap, vUv).xyz * 2.0 - 1.0;
  t.xy *= normalStrength;
  N = normalize(E * t.x + Nn * t.y + Ng * max(t.z, 0.05));
#endif
  float mu = dot(Ng, L);
  float day = smoothstep(-twilight * 0.5, twilight, mu);
  vec3 albedo = texture2D(dayMap, vUv).rgb;
  float water = texture2D(waterMap, vUv).r;

  float shade = 0.0;
  float cover = 0.0;
#ifdef USE_CLOUDS
  vec2 cuv = vec2(vUv.x - cloudOffset, vUv.y);
  cover = cloudCover(cuv) * cloudAmount;
  float cosLat = max(0.2, sqrt(max(0.0, 1.0 - dot(Ng, axisW) * dot(Ng, axisW))));
  vec2 shift = vec2(dot(L, E), dot(L, Nn)) * cloudHeight / max(mu, 0.25);
  shade = cloudCover(cuv + vec2(shift.x / (2.0 * PI * cosLat), shift.y / PI)) * cloudShadow * cloudAmount;
#endif

  // Khuếch tán: ánh sáng có sắc đỏ cam khi Mặt Trời thấp (đường đi qua khí quyển dài).
  float lowSun = 1.0 - smoothstep(0.0, 0.45, mu);
  vec3 sunTint = mix(vec3(1.0), vec3(1.0, 0.62, 0.38), lowSun * 0.85);
  // Bán dạ: cường độ giảm mềm về 0 hơi quá đường phân chia (khúc xạ + đĩa Mặt Trời có bề rộng).
  float diff = max(dot(N, L) + 0.04, 0.0) / 1.04 * smoothstep(-twilight * 0.6, twilight * 0.4, mu);
  vec3 col = albedo * sunColor * sunTint * sunIntensity * diff * (1.0 - shade);

  // Phản xạ gương trên biển (vệt sáng Mặt Trời) + Fresnel nhẹ.
  vec3 H = normalize(L + V);
  float nh = max(dot(Ng, H), 0.0);
  float fres = 0.04 + 0.96 * pow(1.0 - max(dot(Ng, V), 0.0), 5.0);
  float spec = (pow(nh, 300.0) * 1.8 + pow(nh, 40.0) * 0.05) * (0.4 + fres);
  col += sunColor * sunTint * sunIntensity * spec * specStrength * water * day * (1.0 - cover) * max(mu, 0.0) * 4.0;

  // Đèn thành phố bên đêm (bị mây che bớt) + ánh trời rất mờ.
  float night = 1.0 - smoothstep(-twilight, twilight * 0.4, mu);
  vec3 lights = texture2D(nightMap, vUv).rgb;
  col += lights * nightGain * night * (1.0 - 0.75 * cover);
  col += albedo * ambient * vec3(0.55, 0.65, 1.0);

  gl_FragColor = vec4(col, 1.0);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}
